package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LendingIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void loaning_a_book_already_on_loan_returns_409() throws Exception {
        String book = registerBook();
        String memberId = registerMember();
        String loanRequest = loanRequest(book, memberId);

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.bookId").value(book));

        String otherMemberRequest = loanRequest(book, registerMember());
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(otherMemberRequest))
                .andExpect(status().isConflict());
    }

    @Test
    void member_cannot_borrow_more_than_five_books_at_once() throws Exception {
        String memberId = registerMember();
        for (int i = 0; i < 5; i++) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(loanRequest(registerBook(), memberId)))
                    .andExpect(status().isCreated());
        }

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));
    }

    @Test
    void loan_limit_is_per_member() throws Exception {
        String fullMember = registerMember();
        for (int i = 0; i < 5; i++) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(loanRequest(registerBook(), fullMember)))
                    .andExpect(status().isCreated());
        }

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), registerMember())))
                .andExpect(status().isCreated());
    }

    @Test
    void loaning_with_unregistered_member_returns_404() throws Exception {
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), UUID.randomUUID().toString())))
                .andExpect(status().isNotFound());
    }

    @Test
    void returning_a_loan_makes_the_book_loanable_again() throws Exception {
        String book = registerBook();
        String loanId = loan(book, registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(book, registerMember())))
                .andExpect(status().isCreated());
    }

    @Test
    void returning_an_already_returned_loan_returns_409() throws Exception {
        String loanId = loan(registerBook(), registerMember());
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RETURNED"));
    }

    @Test
    void returning_an_unknown_loan_returns_404() throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void returned_loans_do_not_count_toward_the_limit() throws Exception {
        String memberId = registerMember();
        String firstLoanId = loan(registerBook(), memberId);
        for (int i = 0; i < 4; i++) {
            loan(registerBook(), memberId);
        }
        mockMvc.perform(post("/loans/{loanId}/return", firstLoanId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), memberId)))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));
    }

    @Test
    void returning_on_the_due_date_has_no_late_fee() throws Exception {
        String loanId = loanOn("2026-01-01", registerBook(), registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-01-15\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value("2026-01-15"))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void returning_one_day_after_the_due_date_charges_100() throws Exception {
        String loanId = loanOn("2026-01-01", registerBook(), registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-01-16\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(1))
                .andExpect(jsonPath("$.lateFee").value(100));
    }

    @Test
    void returning_five_days_after_the_due_date_charges_500() throws Exception {
        String loanId = loanOn("2026-01-01", registerBook(), registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-01-20\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(5))
                .andExpect(jsonPath("$.lateFee").value(500));
    }

    @Test
    void returning_without_a_body_uses_today() throws Exception {
        String loanId = loan(registerBook(), registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void returning_before_the_loan_date_returns_400() throws Exception {
        String loanId = loanOn("2026-01-01", registerBook(), registerMember());

        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2025-12-31\"}"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void member_loans_list_only_active_loans_with_book_title() throws Exception {
        String memberId = registerMember();
        String returnedLoanId = loanOn("2026-02-01", registerBook(), memberId);
        String activeLoanId = loanOn("2026-02-02", registerBook(), memberId);
        mockMvc.perform(post("/loans/{loanId}/return", returnedLoanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-02-03\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].loanId").value(activeLoanId))
                .andExpect(jsonPath("$.items[0].title").value("Clean Architecture"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-02"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-16"))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(20))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void member_loans_are_paged_and_total_count_ignores_page() throws Exception {
        String memberId = registerMember();
        String firstLoanId = loanOn("2026-02-01", registerBook(), memberId);
        String secondLoanId = loanOn("2026-02-02", registerBook(), memberId);
        String thirdLoanId = loanOn("2026-02-03", registerBook(), memberId);

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "0").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].loanId").value(firstLoanId))
                .andExpect(jsonPath("$.items[1].loanId").value(secondLoanId))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(2))
                .andExpect(jsonPath("$.totalCount").value(3));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "1").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].loanId").value(thirdLoanId))
                .andExpect(jsonPath("$.totalCount").value(3));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "2").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(0))
                .andExpect(jsonPath("$.totalCount").value(3));
    }

    @Test
    void member_loans_for_unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void member_loans_with_invalid_paging_returns_400() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "-1"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "0"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "101"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void discarding_a_book_returns_discarded_status() throws Exception {
        String book = registerBook();

        mockMvc.perform(post("/books/{bookId}/discard", book))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value(book))
                .andExpect(jsonPath("$.title").value("Clean Architecture"))
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarding_a_book_twice_keeps_it_discarded() throws Exception {
        String book = registerBook();
        mockMvc.perform(post("/books/{bookId}/discard", book)).andExpect(status().isOk());

        mockMvc.perform(post("/books/{bookId}/discard", book))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void loaning_a_discarded_book_returns_409() throws Exception {
        String book = registerBook();
        mockMvc.perform(post("/books/{bookId}/discard", book)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(book, registerMember())))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void discarding_a_book_on_loan_returns_409() throws Exception {
        String book = registerBook();
        loan(book, registerMember());

        mockMvc.perform(post("/books/{bookId}/discard", book))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_ON_LOAN"));
    }

    @Test
    void book_can_be_discarded_after_it_is_returned() throws Exception {
        String book = registerBook();
        String loanId = loan(book, registerMember());
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(post("/books/{bookId}/discard", book))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarding_an_unknown_book_returns_404() throws Exception {
        mockMvc.perform(post("/books/{bookId}/discard", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private String loanOn(String loanedAt, String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId, loanedAt)))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.loanedAt").value(loanedAt))
                .andExpect(jsonPath("$.dueAt").value(LocalDate.parse(loanedAt).plusDays(14).toString()))
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String loan(String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.status").value("AVAILABLE"))
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"이준호\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String loanRequest(String bookId, String memberId) throws Exception {
        return loanRequest(bookId, memberId, null);
    }

    private String loanRequest(String bookId, String memberId, String loanedAt) throws Exception {
        return objectMapper.writeValueAsString(new LoanBody(bookId, memberId, loanedAt));
    }

    record LoanBody(String bookId, String memberId, String loanedAt) {
    }
}
